void tearDown(void) { }

void unit_test_createNode_basic_content_initialization(void) {
    // Setup: choose a test character
    char test_content = 'A';

    // Test: call createNode
    struct ASTNode* node = createNode(test_content);

    // Assertions
    TEST_ASSERT_NOT_NULL(node);
    TEST_ASSERT_EQUAL(test_content, node->content);
    TEST_ASSERT_NULL(node->left);
    TEST_ASSERT_NULL(node->right);

    // Cleanup
    free(node);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_createNode_basic_content_initialization);
    return UNITY_END();
}

